fn decode_cyclic(s: &Vec<i8>) -> Vec<i8> {
    let len = s.len();
    // P = largest multiple of 3 not exceeding len
    let p = len - (len % 3);

    // Pre-allocate result of the same length
    let mut res = Vec::with_capacity(len);

    // Decode each full triplet by a right-rotation: (x,y,z) → (z,x,y)
    for i in 0..p {
        if i % 3 == 0 {
            // position 3k → gets original 3k+2
            res.push(s[i + 2]);
        } else {
            // positions 3k+1 or 3k+2 → both get original i-1
            res.push(s[i - 1]);
        }
    }

    // Copy any remaining tail (len mod 3) unchanged
    for i in p..len {
        res.push(s[i]);
    }

    res
}

